import path from "node:path";
import { pathToFileURL } from "node:url";

const indexPath = "c:/Users/016551/OneDrive/Desktop/流程建设/north-america-trend-digest-master/desktop/src/index.html";
const url = pathToFileURL(indexPath).href;
const outDir = "C:/Users/016551/AppData/Local/Temp/widget-shot";

const mock = {
  archiveDate: "2026-06-10",
  nextRefreshBeijing: "2026-06-11 08:00",
  generatedAt: "2026-06-10T00:02:00Z",
  ai: {
    status: "ready",
    generatedAt: "2026-06-10T00:02:00Z",
    executiveSummary:
      "今日重点集中在世界杯北美落地带来的入境、票务与城市消费讨论;产品侧音频引领可穿戴更新密集。AirPods 自适应 EQ、便携音箱续航与零售体验值得关注;网感上 Backrooms/Godzilla 类迷因网梗在上升。",
    executiveBullets: [
      { topic: "世界杯城市热点", point: "世界杯相关入境与票务争议正在影响北美城市体验、旅游消费与品牌上下窗口判断。" },
      { topic: "消费电子趋势", point: "音频产品围绕个性化调音、长续航便携和 AI 生态联动持续升级;可穿戴则暴露固件稳定痛点。" },
      { topic: "网感培养建议", point: "Backrooms、Godzilla 等高语境 meme 走热,适合做视觉化短视频与评论区互动,但需先确认语境。" },
    ],
  },
  products: [
    { zhTitle: "AirPods 自适应 EQ 据称将随固件更新扩展机型", zhSummary: "新固件把自适应均衡下放到更多机型,主打通勤场景的低频补偿与人声清晰度。", source: "9to5Mac", ageHours: 3, priorityLabel: "高", marketingTip: "可对标韶音骨传导在通勤场景的清晰度叙事。" },
    { zhTitle: "便携蓝牙音箱续航普遍冲击 24 小时档", zhSummary: "多家厂商把户外便携音箱续航推到 24h,并强化 IP67 与挂绳零售陈列。", source: "The Verge", ageHours: 7, priorityLabel: "中" },
    { zhTitle: "可穿戴固件更新引发心率读数争议", zhSummary: "部分用户反馈更新后心率读数漂移,厂商称将回滚问题批次。", source: "Wareable", ageHours: 11, priorityLabel: "中" },
  ],
};

const themes = ["grid", "paper", "ink"];
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 380, height: 600 }, deviceScaleFactor: 2 });

await page.route("**/api/digest*", (route) =>
  route.fulfill({ status: 200, contentType: "application/json", body: JSON.stringify(mock) }),
);

await page.goto(url, { waitUntil: "networkidle" });
// simulate a wallpaper behind the translucent shell
await page.addStyleTag({
  content: "html{background:linear-gradient(135deg,#4a5a6a 0%,#2b3a4a 40%,#6a5a7a 100%)!important;}",
});
await page.waitForTimeout(400);

async function shot(theme, section, name) {
  await page.evaluate(
    ([t, s]) => {
      document.documentElement.dataset.theme = t;
      const btn = document.querySelector(`.tab[data-section="${s}"]`);
      if (btn) btn.click();
    },
    [theme, section],
  );
  await page.waitForTimeout(300);
  await page.screenshot({ path: path.join(outDir, name) });
}

await shot("grid", "brief", "grid-brief.png");
await shot("grid", "products", "grid-products.png");
await shot("paper", "products", "paper-products.png");
await shot("ink", "products", "ink-products.png");

await browser.close();
console.log("done");

